import re


def apply_patch(original: str, diff: str) -> str:
    """Apply a unified diff to original text and return the patched result."""

    def splitlines_keepends(text):
        if not text:
            return []
        lines = []
        i = 0
        n = len(text)
        while i < n:
            nl = text.find('\n', i)
            if nl == -1:
                lines.append(text[i:])
                break
            else:
                lines.append(text[i:nl + 1])
                i = nl + 1
        return lines

    original_lines = splitlines_keepends(original)

    hunk_pattern = re.compile(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@')

    diff_lines = diff.split('\n')

    hunks = []
    i = 0
    n = len(diff_lines)
    while i < n:
        line = diff_lines[i]
        m = hunk_pattern.match(line)
        if m:
            old_start = int(m.group(1))
            old_count = int(m.group(2)) if m.group(2) is not None else 1
            new_start = int(m.group(3))
            new_count = int(m.group(4)) if m.group(4) is not None else 1

            body_lines = []
            j = i + 1
            while j < n:
                bl = diff_lines[j]
                if bl.startswith(' ') or bl.startswith('-') or bl.startswith('+'):
                    body_lines.append(bl)
                    j += 1
                elif bl == '\\':
                    if j + 1 < n and diff_lines[j + 1].strip() == 'No newline at end of file':
                        body_lines.append('\\')
                        j += 2
                    else:
                        break
                else:
                    break

            hunks.append((old_start, old_count, new_start, new_count, body_lines))
            i = j
        else:
            i += 1

    if not hunks:
        return original

    result = []
    consumed = 0  # Number of original_lines already processed

    for old_start, old_count, new_start, new_count, body_lines in hunks:
        # Verify counts
        actual_old_count = sum(1 for bl in body_lines if bl.startswith(' ') or bl.startswith('-'))
        actual_new_count = sum(1 for bl in body_lines if bl.startswith(' ') or bl.startswith('+'))

        if actual_old_count != old_count:
            raise ValueError(f"Old count mismatch: header={old_count}, body={actual_old_count}")
        if actual_new_count != new_count:
            raise ValueError(f"New count mismatch: header={new_count}, body={actual_new_count}")

        # Actual 0-indexed position in original_lines
        pos = old_start - 1

        if pos < consumed:
            raise ValueError("Hunk overlaps with previous hunk")

        if pos > len(original_lines):
            raise ValueError(f"Hunk start out of range: {pos}")

        end_pos = pos + old_count
        if end_pos > len(original_lines):
            raise ValueError("Hunk extends beyond end of file")

        # Verify context and removed lines match
        seg_idx = 0
        for bl in body_lines:
            if bl == '\\':
                continue
            if bl.startswith(' '):
                expected = bl[1:]
                actual = original_lines[pos + seg_idx]
                if expected != actual:
                    raise ValueError(f"Context mismatch at line {old_start + seg_idx}")
                seg_idx += 1
            elif bl.startswith('-'):
                expected = bl[1:]
                actual = original_lines[pos + seg_idx]
                if expected != actual:
                    raise ValueError(f"Removed line mismatch at line {old_start + seg_idx}")
                seg_idx += 1

        # Build new segment with no-newline handling
        new_no_newline = set()
        for idx, bl in enumerate(body_lines):
            if bl == '\\':
                prev_idx = idx - 1
                while prev_idx >= 0 and body_lines[prev_idx] == '\\':
                    prev_idx -= 1
                if prev_idx < 0:
                    raise ValueError("Backslash without preceding line")
                if body_lines[prev_idx].startswith('+') or body_lines[prev_idx].startswith(' '):
                    new_no_newline.add(prev_idx)

        new_segment = []
        for idx, bl in enumerate(body_lines):
            if bl == '\\':
                continue
            if bl.startswith(' ') or bl.startswith('+'):
                content = bl[1:]
                if idx in new_no_newline:
                    if content.endswith('\n'):
                        content = content[:-1]
                new_segment.append(content)

        # Append lines from consumed to pos (unchanged), then the new segment
        result.extend(original_lines[consumed:pos])
        result.extend(new_segment)

        consumed = end_pos

    # Append remaining lines
    result.extend(original_lines[consumed:])

    return ''.join(result)
