                lines.append(text[i:])
                break
            else:
                lines.append(text[i:nl + 1])
                i = nl + 1
        return lines

    original_lines = splitlines_keepends(original)

    hunk_pattern = re.compile(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@')

    # Parse diff into hunks. Each body line is stored as (prefix_char, content_without_newline, has_trailing_newline)
    # where has_trailing_newline indicates whether the line in the diff had a trailing newline.

    # Split diff preserving line endings
    diff_lines = []
    i = 0
    n = len(diff)
    while i < n:
        nl = diff.find('\n', i)
        if nl == -1:
            line = diff[i:]
            has_nl = False
            # Strip trailing \r for CRLF
            if line.endswith('\r'):
                line = line[:-1]
            diff_lines.append((line, has_nl))
            break
        else:
            line = diff[i:nl + 1]  # include the \n
            has_nl = True
            # Check for CRLF
            if line.endswith('\r\n'):
                content = line[:-2]
            else:
                content = line[:-1]  # just strip \n
            diff_lines.append((content, has_nl))
            i = nl + 1

    hunks = []
    idx = 0
    total = len(diff_lines)
    while idx < total:
        line_text, _ = diff_lines[idx]
        m = hunk_pattern.match(line_text)
        if m:
            old_start = int(m.group(1))
            old_count = int(m.group(2)) if m.group(2) is not None else 1
            new_start = int(m.group(3))
            new_count = int(m.group(4)) if m.group(4) is not None else 1

            body_lines = []
            j = idx + 1
            while j < total:
                bl_text, bl_has_nl = diff_lines[j]
                if bl_text.startswith(' ') or bl_text.startswith('-') or bl_text.startswith('+'):
                    prefix = bl_text[0]
                    content = bl_text[1:]
                    body_lines.append((prefix, content, bl_has_nl))
                    j += 1
                elif bl_text == '\\':
                    if j + 1 < total and diff_lines[j + 1][0].strip() == 'No newline at end of file':
                        body_lines.append(('\\', '', False))
                        j += 2
                    else:
                        break
                else:
                    break

            hunks.append((old_start, old_count, new_start, new_count, body_lines))
            idx = j
        else:
            idx += 1

    if not hunks:
        return original

    result = []
    consumed = 0

    for old_start, old_count, new_start, new_count, body_lines in hunks:
        # Verify counts (exclude backslash markers)
        actual_old_count = sum(1 for p, _, _ in body_lines if p == ' ' or p == '-')
        actual_new_count = sum(1 for p, _, _ in body_lines if p == ' ' or p == '+')

        if actual_old_count != old_count:
            raise ValueError(f"Old count mismatch: header={old_count}, body={actual_old_count}")
        if actual_new_count != new_count:
            raise ValueError(f"New count mismatch: header={new_count}, body={actual_new_count}")

        # Actual 0-indexed position in original_lines
        pos = old_start - 1

        if pos < consumed:
            raise ValueError("Hunk overlaps with previous hunk")

        if pos > len(original_lines):
            raise ValueError(f"Hunk start out of range: {pos}")

        end_pos = pos + old_count
        if end_pos > len(original_lines):
            raise ValueError("Hunk extends beyond end of file")

        # Verify context and removed lines match by comparing content without newlines
        seg_idx = 0
        for prefix, content, _ in body_lines:
            if prefix == '\\':
                continue
            if prefix == ' ':
                actual_line = original_lines[pos + seg_idx]
                # Strip newline from actual line for comparison
                if actual_line.endswith('\n'):
                    actual_content = actual_line[:-1]
                else:
                    actual_content = actual_line
                if content != actual_content:
                    raise ValueError(f"Context mismatch at line {old_start + seg_idx}")
                seg_idx += 1
            elif prefix == '-':
                actual_line = original_lines[pos + seg_idx]
                if actual_line.endswith('\n'):
                    actual_content = actual_line[:-1]
                else:
                    actual_content = actual_line
                if content != actual_content:
                    raise ValueError(f"Removed line mismatch at line {old_start + seg_idx}")
                seg_idx += 1

        # Determine which new-version lines have no trailing newline
        # A backslash marker after a '+' or ' ' line means that line has no trailing newline in the new version
        new_no_newline = set()
        for bidx, (prefix, _, _) in enumerate(body_lines):
            if prefix == '\\':
                # Find the immediately preceding non-backslash body line
                prev_idx = bidx - 1
                while prev_idx >= 0 and body_lines[prev_idx][0] == '\\':
                    prev_idx -= 1
                if prev_idx < 0:
                    raise ValueError("Backslash without preceding line")
                prev_prefix = body_lines[prev_idx][0]
                if prev_prefix in ('+', ' '):
                    new_no_newline.add(prev_idx)

        # Build new segment
        new_segment = []
        for bidx, (prefix, content, has_nl) in enumerate(body_lines):
            if prefix == '\\':
                continue
            if prefix in (' ', '+'):
                if bidx in new_no_newline:
                    # No trailing newline
                    new_segment.append(content)
                else:
                    # Has trailing newline - use \n as the line ending
                    new_segment.append(content + '\n')

        # Append unchanged lines before this hunk, then the new segment
        result.extend(original_lines[consumed:pos])
        result.extend(new_segment)

        consumed = end_pos

    # Append remaining lines
    result.extend(original_lines[consumed:])

    return ''.join(result)
