from __future__ import annotations


# Token types
TOK_INT = "INT"
TOK_FLOAT = "FLOAT"
TOK_IDENT = "IDENT"
TOK_OP = "OP"
TOK_LPAREN = "LPAREN"
TOK_RPAREN = "RPAREN"
TOK_COMMA = "COMMA"
TOK_EOF = "EOF"


class _Token:
    __slots__ = ("kind", "value")

    def __init__(self, kind: str, value):
        self.kind = kind
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.kind!r}, {self.value!r})"


_TWO_CHAR_OPS = ("==", "!=", "<=", ">=")


def _tokenize(expr: str) -> list[_Token]:
    tokens: list[_Token] = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]

        if ch.isspace():
            i += 1
            continue

        if i + 1 < n and expr[i : i + 2] in _TWO_CHAR_OPS:
            tokens.append(_Token(TOK_OP, expr[i : i + 2]))
            i += 2
            continue

        if ch in "+-*/%^<>=!&|?":
            tokens.append(_Token(TOK_OP, ch))
            i += 1
            continue

        if ch == "(":
            tokens.append(_Token(TOK_LPAREN, "("))
            i += 1
            continue

        if ch == ")":
            tokens.append(_Token(TOK_RPAREN, ")"))
            i += 1
            continue

        if ch == ",":
            tokens.append(_Token(TOK_COMMA, ","))
            i += 1
            continue

        if ch.isdigit() or (ch == "." and i + 1 < n and expr[i + 1].isdigit()):
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            if i < n and expr[i] == ".":
                i += 1
                while i < n and expr[i].isdigit():
                    i += 1
            text = expr[start:i]
            if "." in text:
                tokens.append(_Token(TOK_FLOAT, float(text)))
            else:
                tokens.append(_Token(TOK_INT, int(text)))
            continue

        if ch.isalpha() or ch == "_":
            start = i
            while i < n and (expr[i].isalnum() or expr[i] == "_"):
                i += 1
            tokens.append(_Token(TOK_IDENT, expr[start:i]))
            continue

        raise SyntaxError(f"Unexpected character {ch!r} at position {i}")

    tokens.append(_Token(TOK_EOF, None))
    return tokens


# --- AST nodes ---

class _IntNode:
    __slots__ = ("val",)

    def __init__(self, val: int):
        self.val = val


class _FloatNode:
    __slots__ = ("val",)

    def __init__(self, val: float):
        self.val = val


class _IdentNode:
    __slots__ = ("name",)

    def __init__(self, name: str):
        self.name = name


class _BinOpNode:
    __slots__ = ("op", "left", "right")

    def __init__(self, op: str, left, right):
        self.op = op
        self.left = left
        self.right = right


class _UnaryOpNode:
    __slots__ = ("op", "operand")

    def __init__(self, op: str, operand):
        self.op = op
        self.operand = operand


class _CallNode:
    __slots__ = ("name", "args")

    def __init__(self, name: str, args: list):
        self.name = name
        self.args = args


class _CondNode:
    __slots__ = ("cond", "true_branch", "false_branch")

    def __init__(self, cond, true_branch, false_branch):
        self.cond = cond
        self.true_branch = true_branch
        self.false_branch = false_branch


# --- Parser (builds AST) ---

class _Parser:
    def __init__(self, tokens: list[_Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> _Token:
        return self.tokens[self.pos]

    def advance(self) -> _Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind: str, value=None) -> _Token:
        tok = self.peek()
        if tok.kind != kind or (value is not None and tok.value != value):
            raise SyntaxError(f"Expected {kind} {value!r} but got {tok!r}")
        return self.advance()

