            self.advance()  # consume '?'
            true_branch = self.parse_conditional()
            self.expect(TOK_OP, ":")
            false_branch = self.parse_conditional()
            return _CondNode(cond, true_branch, false_branch)
        return cond

    # 2. || (lowest logical precedence)
    def parse_or(self):
        left = self.parse_and()
        while self._peek_op("||"):
            self.advance()
            right = self.parse_and()
            left = _BinOpNode("||", left, right)
        return left

    # 2. && (higher than ||)
    def parse_and(self):
        left = self.parse_comparison()
        while self._peek_op("&&"):
            self.advance()
            right = self.parse_comparison()
            left = _BinOpNode("&&", left, right)
        return left

    # 3. Comparisons (non-associative)
    def parse_comparison(self):
        left = self.parse_additive()
        tok = self.peek()
        if tok.kind == TOK_OP and tok.value in ("==", "!=", "<", "<=", ">", ">="):
            self.advance()
            right = self.parse_additive()
            # Check for non-associativity: next token must not be another comparison operator
            nxt = self.peek()
            if nxt.kind == TOK_OP and nxt.value in ("==", "!=", "<", "<=", ">", ">="):
                raise SyntaxError(f"Non-associative comparison: {nxt.value!r} after another comparison")
            return _BinOpNode(tok.value, left, right)
        return left

    # 4. Additive: + - (left-associative)
    def parse_additive(self):
        left = self.parse_multiplicative()
        while True:
            tok = self.peek()
            if tok.kind == TOK_OP and tok.value in ("+", "-"):
                self.advance()
                right = self.parse_multiplicative()
                left = _BinOpNode(tok.value, left, right)
            else:
