        left = self.parse_unary()
        while True:
            tok = self.peek()
            if tok.kind == TOK_OP and tok.value in ("*", "/", "%"):
                self.advance()
                right = self.parse_unary()
                left = _BinOpNode(tok.value, left, right)
            else:
                break
        return left

    # 6. Unary: - + ! (prefix)
    def parse_unary(self):
        tok = self.peek()
        if tok.kind == TOK_OP and tok.value in ("-", "+", "!"):
            self.advance()
            operand = self.parse_unary()
            return _UnaryOpNode(tok.value, operand)
        return self.parse_power()

    # 7. Power: ^ (right-associative)
    def parse_power(self):
        base = self.parse_atom()
        if self.peek().kind == TOK_OP and self.peek().value == "^":
            self.advance()
            exponent = self.parse_unary()
            return _BinOpNode("^", base, exponent)
        return base

    # 8. Atoms
    def parse_atom(self):
        tok = self.peek()

        if tok.kind == TOK_INT:
            self.advance()
            return _IntNode(tok.value)

        if tok.kind == TOK_FLOAT:
            self.advance()
            return _FloatNode(tok.value)

        if tok.kind == TOK_IDENT:
            name = tok.value
            self.advance()
            if self.peek().kind == TOK_LPAREN:
