                args = self._parse_arg_list()
                self.expect(TOK_RPAREN, ")")
                return _CallNode(name, args)
            else:
                return _IdentNode(name)

        if tok.kind == TOK_LPAREN:
            self.advance()
            node = self.parse_conditional()
            self.expect(TOK_RPAREN, ")")
            return node

        raise SyntaxError(f"Unexpected token {tok!r}")

    def _parse_arg_list(self) -> list:
        args = []
        if self.peek().kind == TOK_RPAREN:
            return args
        args.append(self.parse_conditional())
        while self.peek().kind == TOK_COMMA:
            self.advance()
            args.append(self.parse_conditional())
        return args

    def _peek_op(self, op: str) -> bool:
        tok = self.peek()
        return tok.kind == TOK_OP and tok.value == op


# --- Evaluator (with short-circuit logic) ---

def _eval(node, env: dict[str, float]) -> int | float:
    if isinstance(node, _IntNode):
        return node.val
    if isinstance(node, _FloatNode):
        return node.val
    if isinstance(node, _IdentNode):
        if node.name in env:
            return env[node.name]
        raise NameError(f"Name {node.name!r} is not defined")
    if isinstance(node, _UnaryOpNode):
        operand = _eval(node.operand, env)
        if node.op == "-":
            return -operand
        elif node.op == "+":
            return +operand
        elif node.op == "!":
            return 1 if operand == 0 else 0
    if isinstance(node, _BinOpNode):
        op = node.op
        # Short-circuit operators
        if op == "||":
            left_val = _eval(node.left, env)
            if left_val != 0:
                return 1
            right_val = _eval(node.right, env)
            return 1 if right_val != 0 else 0
        if op == "&&":
            left_val = _eval(node.left, env)
            if left_val == 0:
                return 0
            right_val = _eval(node.right, env)
            return 1 if right_val != 0 else 0
        # Normal binary operators (evaluate both sides)
        left_val = _eval(node.left, env)
        right_val = _eval(node.right, env)
        if op == "+":
            return left_val + right_val
        elif op == "-":
            return left_val - right_val
        elif op == "*":
            return left_val * right_val
        elif op == "/":
            if right_val == 0:
                raise ZeroDivisionError("division by zero")
            if isinstance(left_val, int) and isinstance(right_val, int):
                if left_val % right_val == 0:
                    return left_val // right_val
                else:
                    return left_val / right_val
            else:
                return left_val / right_val
        elif op == "%":
            if right_val == 0:
                raise ZeroDivisionError("modulo by zero")
            return left_val % right_val
        elif op == "^":
            return left_val ** right_val
        elif op == "==":
            return 1 if left_val == right_val else 0
        elif op == "!=":
            return 1 if left_val != right_val else 0
        elif op == "<":
            return 1 if left_val < right_val else 0
        elif op == "<=":
            return 1 if left_val <= right_val else 0
        elif op == ">":
            return 1 if left_val > right_val else 0
        elif op == ">=":
            return 1 if left_val >= right_val else 0
    if isinstance(node, _CallNode):
        args = [_eval(a, env) for a in node.args]
        name = node.name
        if name == "min":
            if len(args) < 1:
                raise SyntaxError("min() requires at least 1 argument")
            result = args[0]
            for a in args[1:]:
                if a < result:
                    result = a
            return result
        elif name == "max":
            if len(args) < 1:
                raise SyntaxError("max() requires at least 1 argument")
            result = args[0]
            for a in args[1:]:
                if a > result:
                    result = a
            return result
        elif name == "abs":
            if len(args) != 1:
                raise SyntaxError("abs() requires exactly 1 argument")
            return abs(args[0])
        else:
            raise NameError(f"Function {name!r} is not defined")
    if isinstance(node, _CondNode):
        cond_val = _eval(node.cond, env)
        if cond_val != 0:
            return _eval(node.true_branch, env)
        else:
            return _eval(node.false_branch, env)
    raise SyntaxError(f"Unknown node type {type(node).__name__}")


def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    if not expr.strip():
        raise SyntaxError("Empty expression")

    tokens = _tokenize(expr)
    parser = _Parser(tokens)
    ast = parser.parse()
    return _eval(ast, env if env is not None else {})
