    if s[0] in ('v', '='):
        s = s[1:]

    if s == "":
        raise ValueError("Empty version after prefix")

    m = _SEMVER_RE.match(s)
    if not m:
        raise ValueError(f"Invalid version: {v}")

    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    prerelease = m.group(4)  # None or string
    build = m.group(5)       # None or string

    # Post-validate prerelease and build for leading zeros etc.
    if prerelease is not None:
        _validate_prerelease_str(prerelease)
    if build is not None:
        _validate_build_str(build)

    return Version(major, minor, patch, prerelease, build)


