@dataclass
class Comparator:
    op: str  # '<', '<=', '>', '>=', '='
    version: Version

    def matches(self, v: Version) -> bool:
        if self.op == "<":
            return v < self.version
        elif self.op == "<=":
            return v <= self.version
        elif self.op == ">":
            return v > self.version
        elif self.op == ">=":
            return v >= self.version
        elif self.op == "=":
            return v == self.version
        return False


def _parse_version_parts(s: str) -> Tuple[Optional[int], Optional[int], Optional[int], Optional[str]]:
    """Parse version parts, allowing X-ranges. Returns (major, minor, patch, prerelease)."""
    s = s.strip()
    if s == "":
        raise ValueError("Empty version")

    # Strip leading v or =
    if s[0] in ('v', '='):
        s = s[1:]

    if s == "":
        raise ValueError("Empty version after prefix")

    # Split off build metadata
    if "+" in s:
        parts = s.split("+", 1)
        s = parts[0]
        _validate_build_str(parts[1])

