    if "-" in s:
        idx = s.rfind("-")
        s_core = s[:idx]
        pre_str = s[idx + 1:]
        prerelease = _validate_prerelease_str(pre_str)
    else:
        s_core = s

    # Parse M.m.p with X support
    parts = s_core.split(".")
    if len(parts) > 3:
        raise ValueError(f"Too many version parts: {s_core}")

    major = None
    minor = None
    patch = None

    for i, part in enumerate(parts):
        if part in ("", "x", "X", "*"):
            continue
        else:
            val = _parse_identifier(part)
            if i == 0:
                major = val
            elif i == 1:
                minor = val
            elif i == 2:
