    """Handle $ expansion starting at position i (which points to '$').
    Returns (expanded_string, new_i) where new_i is the position after the expanded construct."""
    n = len(line)
    if i >= n or line[i] != '$':
        return '', i

    i += 1  # skip $

    if i >= n:
        # Trailing $ - literal
        return '$', i

    c = line[i]

    if c == '{':
