            value = env.get(name, '')
            return value, i + 1
        elif c == ':' and i + 1 < n and line[i + 1] == '-':
            # ${NAME:-default}
            i += 2  # skip :-
            default_start = i
            while i < n and line[i] != '}':
                i += 1
            if i >= n:
                raise ValueError("Unterminated ${")
            default_text = line[default_start:i]
            expanded_default, _ = _expand_all(default_text, env)
            value = env.get(name, '')
            if value == '':  # unset or empty
                return expanded_default, i + 1
            else:
                return value, i + 1
        elif c == '-':
            # ${NAME-default}
            i += 1  # skip -
            default_start = i
            while i < n and line[i] != '}':
                i += 1
            if i >= n:
                raise ValueError("Unterminated ${")
            default_text = line[default_start:i]
            expanded_default, _ = _expand_all(default_text, env)
            value = env.get(name, '')
            if name not in env:  # only if unset
                return expanded_default, i + 1
            else:
                return value, i + 1
        else:
            raise ValueError("Unterminated ${")

    elif c.isalpha() or c == '_':
        # $NAME - longest [A-Za-z_][A-Za-z0-9_]*
        start = i
        while i < n and (line[i].isalnum() or line[i] == '_'):
            i += 1
        name = line[start:i]
        value = env.get(name, '')
        return value, i

    else:
        # $ not followed by name or { is literal
        return '$', i


def _expand_all(text: str, env: dict[str, str]) -> tuple[str, int]:
    """Expand all $ references in a text string. Returns (expanded_text, final_index)."""
    result = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == '$':
            expanded, new_i = _expand(text, i, env)
            result.append(expanded)
            i = new_i
        else:
            result.append(text[i])
            i += 1
    return ''.join(result), i


def _split_on_whitespace(s: str) -> list[str]:
    """Split on spaces, tabs, and newlines. Returns list of fields."""
    if not s:
        return []
    fields = []
    current = []
    for c in s:
        if c in (' ', '\t', '\n'):
            if current:
                fields.append(''.join(current))
                current = []
        else:
            current.append(c)
    if current:
        fields.append(''.join(current))
    return fields
