    kwargs = {}
    field_names = set()

    for field in fields:
        fname = field.name
        field_names.add(fname)

        if fname not in data:
            # Check for default or default_factory
            if field.default is not dataclasses.MISSING:
                kwargs[fname] = field.default
            elif field.default_factory is not dataclasses.MISSING:
                kwargs[fname] = field.default_factory()
            else:
                raise LoadError(f"{path}.{fname}", f"Missing required field '{fname}'")
        else:
            # Load the value using the resolved annotation from get_type_hints
            annotation = hints.get(fname, Any)
            kwargs[fname] = _load_value(annotation, data[fname], f"{path}.{fname}", globalns)

    # Check for unknown keys - first unknown key in input dict's order
    for key in data.keys():
        if key not in field_names:
            raise LoadError(f"{path}.{key}", f"Unknown field '{key}'")

